            <Tabs id="list-items-5-archive-tabs" ariaLabel="Archive views" selectedId={collectionQuery.archived ? 'archived' : 'active'} items={[{ id: 'active', label: 'Active', panel: (collectionQuery.archived ? 'archived' : 'active') === 'active' ? (<><section id="list-items-5" data-oods-collection="rows">{rows.length === 0 ? (<Banner id="list-items-5-empty" data-oods-component="Banner" content="No records found." />) : (<ol aria-label="Records" className="oods-collection">{rows.map(({ status, stateHistory, allowedTransitions, createdAt, updatedAt, lastEvent, lastEventAt, unitAmountCents, currency, pricingModel, billingInterval, taxBehavior, cancelAtPeriodEnd, cancellationReason, cancellationReasonCode, cancellationRequestedAt, isArchived, archivedAt, restoredAt, archiveReason, archivedBy, archiveMetadata, restorationMetadata, transactionId, userId, organizationId, occurredAt, paymentMethod, channel, paymentReference, riskScore }, collectionIndex) => <li key={String(transactionId)}><ArchivedRowOverlay id={'ve-items-13-' + collectionIndex} data-oods-component="ArchivedRowOverlay" separateTab showBadge tabLabel="Archived" isArchived={isArchived} label={transactionId}>
                    <Button id={'list-items-5-row-' + collectionIndex} type="button" className="oods-collection-row" data-record-id={String(transactionId)} onClick={() => handleRowClick(String(transactionId))}><Text id={'list-items-5-title-' + collectionIndex} data-oods-component="Text">{transactionId}</Text>
                    <StatusBadge id={'ve-items-10-' + collectionIndex} data-oods-component="StatusBadge" tone="lifecycle" status={status} />
                    <RelativeTimestamp id={'ve-items-11-' + collectionIndex} data-oods-component="RelativeTimestamp" datetime={updatedAt ?? createdAt} />
                    <PriceBadge id={'ve-items-12-' + collectionIndex} data-oods-component="PriceBadge" amount={unitAmountCents} currency={currency} /></Button>
                  </ArchivedRowOverlay></li>)}</ol>)}</section></>) : null }, { id: 'archived', label: 'Archived', panel: (collectionQuery.archived ? 'archived' : 'active') === 'archived' ? (<><section id="list-items-5" data-oods-collection="rows">{rows.length === 0 ? (<Banner id="list-items-5-empty" data-oods-component="Banner" content="No records found." />) : (<ol aria-label="Records" className="oods-collection">{rows.map(({ status, stateHistory, allowedTransitions, createdAt, updatedAt, lastEvent, lastEventAt, unitAmountCents, currency, pricingModel, billingInterval, taxBehavior, cancelAtPeriodEnd, cancellationReason, cancellationReasonCode, cancellationRequestedAt, isArchived, archivedAt, restoredAt, archiveReason, archivedBy, archiveMetadata, restorationMetadata, transactionId, userId, organizationId, occurredAt, paymentMethod, channel, paymentReference, riskScore }, collectionIndex) => <li key={String(transactionId)}><ArchivedRowOverlay id={'ve-items-13-' + collectionIndex} data-oods-component="ArchivedRowOverlay" separateTab showBadge tabLabel="Archived" isArchived={isArchived} label={transactionId}>
                    <Button id={'list-items-5-row-' + collectionIndex} type="button" className="oods-collection-row" data-record-id={String(transactionId)} onClick={() => handleRowClick(String(transactionId))}><Text id={'list-items-5-title-' + collectionIndex} data-oods-component="Text">{transactionId}</Text>
                    <StatusBadge id={'ve-items-10-' + collectionIndex} data-oods-component="StatusBadge" tone="lifecycle" status={status} />
                    <RelativeTimestamp id={'ve-items-11-' + collectionIndex} data-oods-component="RelativeTimestamp" datetime={updatedAt ?? createdAt} />
                    <PriceBadge id={'ve-items-12-' + collectionIndex} data-oods-component="PriceBadge" amount={unitAmountCents} currency={currency} /></Button>
                  </ArchivedRowOverlay></li>)}</ol>)}</section></>) : null }]} onChange={(id) => handleFilter({ ...collectionQuery, archived: id === 'archived' })} />
            <Stack id="list-pagination-7" data-oods-component="Stack" data-layout="inline" style={{ display: 'flex', flexDirection: 'row', justifyContent: 'center', padding: 'var(--ref-space-inset-default)' }}>
                    <PaginationBar id="slot-pagination-8" page={collectionQuery.page ?? 1} pageSize={collectionQuery.pageSize ?? 10} totalItems={collectionQuery.total ?? rows.length} onPageChange={handlePageChange} />
                  </Stack>
          </Stack>
    </>
  );
};
